const budgetLimit=3000000;const budgetState={route:0,stay:0,day:0};function money(text){return Number((text||'').replace(/[^0-9]/g,''))||0}function formatBudget(value){return '₮'+new Intl.NumberFormat('en-US').format(value)}function updateBudget(){const total=budgetState.route+budgetState.stay+budgetState.day;const totalEl=document.querySelector('#budgetTotal'),deltaEl=document.querySelector('#budgetDelta'),fillEl=document.querySelector('#budgetFill');if(!budgetState.route){totalEl.textContent='Сонголт хүлээж байна';deltaEl.textContent='Маршрутаа сонгоно уу';fillEl.style.width='0%';return}totalEl.textContent=formatBudget(total);const difference=budgetLimit-total;deltaEl.textContent=difference>=0?formatBudget(difference)+' үлдлээ':formatBudget(Math.abs(difference))+' илүү';fillEl.style.width=Math.min(100,Math.round(total/budgetLimit*100))+'%'}
