const chatStoreKey='zam-chat-history-v1',activeChatKey='zam-active-chat-v1',chatGreeting='Сайн уу. Хаашаа, хэдэн хүн, ямар төсөвтэй явахаа бичээрэй.';let chatThreads=[],activeChatId='';
function saveChats(){try{chatThreads=chatThreads.slice(0,20);localStorage.setItem(chatStoreKey,JSON.stringify(chatThreads));localStorage.setItem(activeChatKey,activeChatId)}catch(e){}}
function currentChat(){return chatThreads.find(chat=>chat.id===activeChatId)}
function addBubble(record){const el=document.createElement('div');el.className='bubble '+record.kind;const body=document.createElement('div');body.textContent=record.text;el.appendChild(body);if(record.sources?.length){const label=document.createElement('div');label.className='source-label';label.textContent='Бодит эх сурвалж';el.appendChild(label);const list=document.createElement('div');list.className='source-list';record.sources.forEach(source=>{if(!source?.url)return;const link=document.createElement('a');link.href=source.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='↗ '+(source.title||'Эх сурвалж');list.appendChild(link)});el.appendChild(list)}messages.appendChild(el)}
