function renderChatHistory(){chatHistoryEl.replaceChildren();[...chatThreads].sort((a,b)=>b.updatedAt-a.updatedAt).forEach(chat=>{const row=document.createElement('div');row.className='chat-history-row';const button=document.createElement('button');button.type='button';button.className='chat-history-item'+(chat.id===activeChatId?' active':'');button.dataset.chatId=chat.id;const title=document.createElement('b');title.textContent=chat.title||'Шинэ аялал';const meta=document.createElement('small');meta.textContent=(chat.messages?.length||0)+' мессеж';button.append(title,meta);const remove=document.createElement('button');remove.type='button';remove.className='chat-delete';remove.dataset.deleteChat=chat.id;remove.setAttribute('aria-label','Яриаг устгах');remove.title='Яриаг устгах';remove.textContent='×';row.append(button,remove);chatHistoryEl.appendChild(row)})}
function createNewChat(){const chat={id:'chat-'+Date.now(),title:'Шинэ аялал',updatedAt:Date.now(),messages:[{text:chatGreeting,kind:'bot',sources:[]}]};chatThreads.unshift(chat);activeChatId=chat.id;saveChats();renderChat();renderChatHistory();document.querySelector('#chatInput').focus()}
