function deleteChat(id){const wasActive=id===activeChatId;chatThreads=chatThreads.filter(chat=>chat.id!==id);if(!chatThreads.length){activeChatId='';createNewChat();return}if(wasActive)activeChatId=chatThreads[0].id;saveChats();renderChat();renderChatHistory()}
