const chatPlanAliases={'Narita Express → Shibuya':['narita','airport express'],'Буудалд check-in + Suica':['check-in','check in','suica','буудалд'],'Shibuya Crossing + Hachikō':['shibuya crossing','hachiko','хачико'],'Nonbei Yokocho оройн хоол':['nonbei','оройн хоол'],'Meiji Jingu сүм':['meiji','мэйжи'],'Harajuku + Takeshita Street':['harajuku','харажүкү','takeshita'],'Shibuya Sky':['shibuya sky','шибүя sky','шибуя sky'],'Shinjuku Omoide Yokocho':['shinjuku','шинжүкү','omoide'],'Sensō-ji · Asakusa':['senso','senso-ji','asakusa','асакуса'],'Ueno Park + музей':['ueno','үэно'],'teamLab Planets':['teamlab','тимлаб'],'Toyosu оройн хоол':['toyosu','тоёосү'],'Tsukiji гадна зах':['tsukiji','цүкижи'],'Ginza сүүлийн shopping':['ginza','гинза'],'Буудлаас ачаагаа авах':['ачаагаа','luggage'],'Narita airport check-in':['airport check','нисэх буудал','нарита']};
function addPlansFromChat(text){const lower=text.toLocaleLowerCase();if(!/(нэм|оруул|сонго|add)/i.test(lower))return[];const matchedDay=lower.match(/([1-4])\s*(?:-?р|\s*дахь)?\s*өд/);const day=matchedDay?Number(matchedDay[1]):activeDay;const program=dayPrograms[day]||dayPrograms[1];const found=program.stops.filter(stop=>{const aliases=[stop[1].toLocaleLowerCase(),...(chatPlanAliases[stop[1]]||[])];return aliases.some(alias=>lower.includes(alias.toLocaleLowerCase()))}).map(stop=>stop[1]);if(!found.length)return[];const chosen=new Set(daySelections[day]||[]);found.forEach(plan=>chosen.add(plan));daySelections[day]=[...chosen];activeDay=day;saveDayChoices();setPlans();updateItineraryStatus();return found}
