function transportPanel(plan){const selected=((dayTransports[activeDay]||{})[plan])||'rail';const options=transportOptions(plan);const chosen=options.find(option=>option[0]===selected)||options[0];const maps='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(plan+', Tokyo, Japan');return '<section class="transport-panel"><div class="transport-head"><span>ЯАЖ ОЧИХ ВЭ?</span><b>'+chosen[1]+' '+chosen[2]+' · '+chosen[3]+'</b></div><div class="transport-options">'+options.map(option=>'<button type="button" class="transport-option '+(option[0]===selected?'active':'')+'" data-transport="'+option[0]+'" data-transport-plan="'+plan+'"><i>'+option[1]+'</i><span><b>'+option[2]+'</b><small>'+option[3]+'</small></span><em>'+((option[0]===selected)?'✓':'Сонгох')+'</em></button>').join('')+'</div><div class="transport-actions"><a href="'+maps+'" target="_blank" rel="noopener">⌖ Чиглэл харах</a><a href="https://www.jreast.co.jp/multi/en/" target="_blank" rel="noopener">🎫 Тасалбар / билет</a><a href="https://go.goinc.jp/" target="_blank" rel="noopener">🚕 Такси дуудах</a></div><p>Үнэ, цаг нь жишиг мэдээлэл. Захиалга хийхийн өмнө үйлчилгээний хуудсан дээр баталгаажуулна.</p></section>'}
