/* Unified travel summary: route, daily program, transport and costs */
function summaryEscape(value){return String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function buildFullTripSummary(){
  const routeName=document.querySelector('#summaryRoute')?.textContent||'Таны сонгосон маршрут';
  const routeDetail=document.querySelector('#summaryDetail')?.textContent||'Улаанбаатар → Токио';
  const routePrice=moneyValue(document.querySelector('#summaryTransport')?.textContent)||0;
  const weather=['⛅ 18° / 11° · Үүлэрхэг','☀️ 20° / 12° · Цэлмэг','🌦️ 17° / 11° · Шиврээ','☀️ 19° / 12° · Цэлмэг'];
  const titles=['Ирсэн өдөр · Shibuya','Harajuku + Shibuya','Урлаг ба хоол','Буцах өдөр'];
  const dateHints=['Нисэх буудал → буудал','Сүм, гудамж, sunset','Asakusa → Toyosu','Ginza → Narita'];
  const days=Object.entries(dayPrograms).map(([day,program])=>{
    const chosen=new Set(daySelections[day]||[]);
    const entries=program.stops.map(stop=>{
      const picked=chosen.has(stop[1]);
      const selectedTransport=(dayTransports[day]||{})[stop[1]]||stop[2];
      return '<li class="summary-stop '+(picked?'is-picked':'')+'"><time>'+summaryEscape(stop[0])+'</time><i>'+summaryEscape(stop[4])+'</i><div><b>'+summaryEscape(stop[1])+'</b><small>'+summaryEscape(selectedTransport)+'</small></div><em>'+summaryEscape(stop[3])+'</em><span>'+ (picked?'Сонгосон':'Санал') +'</span></li>';
    }).join('');
    return '<article class="day-route-card"><header><div><span>ӨДӨР '+String(day).padStart(2,'0')+'</span><h3>'+titles[Number(day)-1]+'</h3><small>'+dateHints[Number(day)-1]+' · '+program.travel+'</small></div><div class="summary-weather">'+weather[Number(day)-1]+'</div></header><ol>'+entries+'</ol></article>';
  }).join('');
  const stayValue=budgetState.stay||0;
  const dayValue=budgetState.day||0;
  const transfer=118000;
  const total=routePrice+stayValue+dayValue+transfer;
  return '<div class="summary-panel summary-panel-full"><button class="close-summary" aria-label="Хаах">×</button><div class="summary-hero"><div><span class="eyebrow">ZAM AI · ТАНЫ НЭГДСЭН АЯЛЛЫН ЗУРАГЛАЛ</span><h2>Нэг харцаар<br><em>бүх аялал.</em></h2><p>'+summaryEscape(routeName)+' · '+summaryEscape(routeDetail)+'</p></div><div class="summary-status"><span>ЯВАХ ХЭЛБЭР</span><b>'+summaryEscape(routeDetail)+'</b><small>Цаг, суудал, хил нэвтрэх нөхцөлийг захиалахдаа дахин баталгаажуулна.</small></div></div><section class="summary-flow"><div class="flow-node active"><i>⌂</i><b>Улаанбаатар</b><small>Бэлтгэл</small></div><div class="flow-leg"><i>✈</i><span>Check-in · нислэг</span></div><div class="flow-node"><i>⌁</i><b>Дамжин суух</b><small>Хэрэв сонгосон бол</small></div><div class="flow-leg"><i>✈</i><span>Arrival · airport rail</span></div><div class="flow-node"><i>⌂</i><b>Токио</b><small>Буудал + Suica</small></div><div class="flow-leg"><i>▣</i><span>Метро · явган</span></div><div class="flow-node gold"><i>★</i><b>4 өдрийн plan</b><small>Таны сонголтууд</small></div></section><section class="summary-dashboard"><article class="summary-now"><span>ОДОО ХААНААС ЭХЛЭХ ВЭ?</span><div><i>✈</i><div><b>Чингис хаан олон улсын нисэх буудал</b><p>Онлайн check-in → ачаа → аюулгүй шалгалт → гарц. Паспорт, виз, даатгалаа гар доороо бэлдээрэй.</p></div></div></article><article class="summary-total"><span>ТООЦООЛСОН НИЙТ</span><b>'+displayMoney(total)+'</b><small>Маршрут '+displayMoney(routePrice)+' · тээвэр '+displayMoney(transfer)+' · буудал '+displayMoney(stayValue)+' · өдөр тутмын plan '+displayMoney(dayValue)+'</small></article></section><section class="summary-itinerary"><div class="summary-itinerary-head"><div><span class="eyebrow">DAY-BY-DAY · LIVE PLAN</span><h3>Өдөр бүрийн <em>маршрут.</em></h3><p>Алтан хүрээтэй нь таны одоогоор сонгосон цэг. Бусад нь хөтөлбөрт нэмэх санал хэвээр байна.</p></div><div class="summary-key"><i></i> Сонгосон цэг <i></i> Санал болгосон цэг</div></div><div class="summary-days">'+days+'</div></section><section class="summary-prep"><div><span class="eyebrow">BEFORE YOU GO</span><h3>Явахын өмнөх <em>checklist.</em></h3></div><ul><li>✓ Паспортын хүчинтэй хугацаа · 6+ сар</li><li>✓ Виз болон дамжин өнгөрөх нөхцөл</li><li>○ Онлайн check-in ба ачааны дүрэм</li><li>○ eSIM, Suica, карт / бэлэн мөнгө</li></ul></section></div>';
}
summaryButton.onclick=()=>{
  const overlay=document.querySelector('#tripSummary');
  overlay.innerHTML=buildFullTripSummary();
  overlay.hidden=false;
  overlay.querySelector('.close-summary').onclick=()=>overlay.hidden=true;
};


/* Single, continuous infographic journey — replaces the card grid */
function buildUnifiedTimelineSummary(){
  const routeName=document.querySelector('#summaryRoute')?.textContent||'Таны сонгосон маршрут';
  const routeDetail=document.querySelector('#summaryDetail')?.textContent||'Улаанбаатар → Токио';
  const routePrice=moneyValue(document.querySelector('#summaryTransport')?.textContent)||0;
  const weather=['⛅ 18° / 11° · Үүлэрхэг','☀️ 20° / 12° · Цэлмэг','🌦️ 17° / 11° · Шиврээ','☀️ 19° / 12° · Цэлмэг'];
  const dayTitles=['Ирсэн өдөр · Shibuya','Harajuku + Shibuya','Урлаг ба хоол','Буцах өдөр'];
  const travelBreaks=['Нарита → Shibuya · Airport Express','Shibuya → Harajuku · метро + явган','Harajuku → Asakusa · Ginza Line','Токио → Нарита · Airport Express'];
  let daily='';
  Object.entries(dayPrograms).forEach(([day,program])=>{
    const chosen=new Set(daySelections[day]||[]);
    daily+='<div class="timeline-day-label"><span>ӨДӨР '+String(day).padStart(2,'0')+'</span><b>'+dayTitles[Number(day)-1]+'</b><em>'+weather[Number(day)-1]+'</em></div>';
    program.stops.forEach((stop,index)=>{
      const isChosen=chosen.has(stop[1]);
      const transport=(dayTransports[day]||{})[stop[1]]||stop[2];
      daily+='<article class="journey-event '+(isChosen?'chosen':'proposal')+'"><div class="journey-time">'+summaryEscape(stop[0])+'</div><div class="journey-pin"><i>'+summaryEscape(stop[4])+'</i></div><div class="journey-copy"><div><span>'+ (isChosen?'ТАНЫ СОНГОЛТ':'НЭМЭХ САНАЛ') +'</span><b>'+summaryEscape(stop[1])+'</b></div><p>'+summaryEscape(transport)+'</p></div><strong>'+summaryEscape(stop[3])+'</strong></article>';
      if(index<program.stops.length-1) daily+='<div class="journey-transfer"><i>↓</i><span>'+summaryEscape(transport)+'</span></div>';
    });
    if(Number(day)<4)daily+='<div class="journey-transfer day-shift"><i>✦</i><span>'+travelBreaks[Number(day)-1]+'</span></div>';
  });
  const total=routePrice+(budgetState.stay||0)+(budgetState.day||0)+118000;
  return '<div class="summary-panel summary-panel-full summary-timeline-panel"><button class="close-summary" aria-label="Хаах">×</button><header class="timeline-summary-head"><span class="eyebrow">ZAM AI · TRIP FLOW</span><h2>Таны аяллын<br><em>нэг урсгал.</em></h2><p>'+summaryEscape(routeName)+' · '+summaryEscape(routeDetail)+'</p><div class="timeline-summary-stats"><span><small>НИЙТ ТООЦОО</small><b>'+displayMoney(total)+'</b></span><span><small>ӨДӨР</small><b>04</b></span><span><small>СОНГОСОН ЦЭГ</small><b>'+Object.values(daySelections).flat().length+'</b></span></div></header><section class="unified-timeline"><article class="journey-event journey-major start"><div class="journey-time">ЭХЛЭЛ</div><div class="journey-pin"><i>⌂</i></div><div class="journey-copy"><span>ОДОО ХИЙХ ЗҮЙЛ</span><b>Улаанбаатар · Чингис хаан ОУБ</b><p>Онлайн check-in → ачаа → аюулгүй шалгалт → гарц</p></div><strong>Паспорт + виз</strong></article><div class="journey-transfer flight"><i>✈</i><span>Нислэг · '+summaryEscape(routeDetail)+'</span></div><article class="journey-event journey-major"><div class="journey-time">ИРЭЛТ</div><div class="journey-pin"><i>⌁</i></div><div class="journey-copy"><span>ХОТ РУУ ОРОХ</span><b>Токио · нисэх буудал</b><p>Airport Express-аар буудал руу → Suica / eSIM идэвхжүүлнэ.</p></div><strong>₮118,000</strong></article>'+daily+'<div class="journey-transfer flight return"><i>✈</i><span>Буцах нислэг · check-in-ээ дахин баталгаажуулна</span></div><article class="journey-event journey-major finish"><div class="journey-time">ДУУСАВ</div><div class="journey-pin"><i>★</i></div><div class="journey-copy"><span>АЯЛЛЫН ТӨГСГӨЛ</span><b>Токио → Улаанбаатар</b><p>Баримт, төлбөр, явах цаг болон буудлын ачаагаа урьдчилж шалгана.</p></div><strong>Safe trip</strong></article></section><footer class="timeline-summary-footer"><div><b>Тайлбар</b><span><i class="legend-picked"></i> Сонгосон цэг</span><span><i class="legend-proposal"></i> Нэмэх санал</span></div><p>Үнэ, цаг, нээлтийн нөхцөлийг тухайн өдрийн бодит нөхцөлтэй уялдуулж операторын эх сурвалжаас баталгаажуулна.</p></footer></div>';
}
summaryButton.onclick=()=>{
  const overlay=document.querySelector('#tripSummary');
  overlay.innerHTML=buildUnifiedTimelineSummary();
  overlay.hidden=false;
  overlay.querySelector('.close-summary').onclick=()=>overlay.hidden=true;
};


/* Summary controls stay visible and always open at the start of the trip flow */
function openUnifiedTripFlow(){
  const overlay=document.querySelector('#tripSummary');
  overlay.innerHTML=buildUnifiedTimelineSummary();
  overlay.scrollTop=0;
  overlay.hidden=false;
  overlay.querySelector('.close-summary').onclick=()=>overlay.hidden=true;
}
summaryButton.onclick=openUnifiedTripFlow;
document.querySelector('#openSummary').onclick=openUnifiedTripFlow;


/* Google Maps embed for the daily travel overview (no API key needed for this demo) */
function renderGoogleTravelMap(){
  const map=document.querySelector('#mapMini');
  if(!map)return;
  map.innerHTML='<iframe class="google-travel-map" title="Токиогийн аяллын газрын зураг" src="https://www.google.com/maps?q=Tokyo%20Japan&z=12&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><a class="google-map-open" href="https://www.google.com/maps/dir/?api=1&destination=Tokyo%2C%20Japan&travelmode=transit" target="_blank" rel="noopener noreferrer">Google Maps дээр чиглэл харах <span>↗</span></a>';
}
renderGoogleTravelMap();
